 public Vector2Int Pick(){return PickAt(Input.mousePosition);}
 public Vector2Int PickAt(Vector3 point){var ray=cam.ScreenPointToRay(point);if(Physics.Raycast(ray,out var hit,100)){var c=hit.collider.GetComponent<CellView>();if(c!=null)return new Vector2Int(c.x,c.y);}return new Vector2Int(-1,-1);}
 void Update(){if(battle==null||!cam.enabled)return;float uiScale=Math.Min(Screen.width/1600f,Screen.height/900f),ox=(Screen.width-1600*uiScale)/2,oy=(Screen.height-900*uiScale)/2;cam.pixelRect=new Rect(ox+190*uiScale,Screen.height-oy-780*uiScale,1220*uiScale,680*uiScale);hover=Pick();if(cam.pixelRect.Contains(Input.mousePosition)){float wheel=Input.mouseScrollDelta.y;if(wheel!=0){zoom=Mathf.Clamp(zoom-wheel*1.5f,9,60);CameraPose();}if(Input.GetMouseButton(1)){focus+=new Vector3(-Input.GetAxis("Mouse X"),0,-Input.GetAxis("Mouse Y"))*.12f;CameraPose();}}
  if(Input.GetKeyDown(KeyCode.R)){focus=new Vector3((battle.width-1)*.5f,0,(battle.height-1)*.5f);zoom=Mathf.Max(battle.height*.87f,battle.width*.58f);CameraPose();}
  Sync();foreach(var u in battle.units.Where(u=>u.Alive)){var tr=figures[u.id].transform;bool moving=Vector3.Distance(tr.position,new Vector3(u.x,0,u.y))>.035f;tr.position=Vector3.Lerp(tr.position,new Vector3(u.x,0,u.y),Time.deltaTime*5);foreach(var limb in tr.GetComponentsInChildren<Stride>())limb.transform.localEulerAngles=limb.rest+new Vector3(moving?Mathf.Sin(Time.time*14+limb.phase)*22:0,0,0);}
  var selectedUnit=battle.units.FirstOrDefault(u=>u.id==selected&&u.Alive);marker.SetActive(selectedUnit!=null);if(selectedUnit!=null)marker.transform.position=new Vector3(selectedUnit.x,0,selectedUnit.y);hoverMarker.SetActive(battle.Contains(hover.x,hover.y));if(battle.Contains(hover.x,hover.y))hoverMarker.transform.position=new Vector3(hover.x,0,hover.y);
  if(Time.time>nextHighlights){nextHighlights=Time.time+.2f;var reach=selectedUnit!=null&&!battle.deployment&&battle.turn==0&&selectedUnit.ap>0?battle.Reach(selectedUnit):new Dictionary<int,int>();foreach(var entry in floors){int x=entry.Key%battle.width,y=entry.Key/battle.width,t=battle.Tile(x,y);Color c=TerrainColor(t,x,y);if(battle.deployment&&battle.InDeployment(0,x,y))c=Color.Lerp(c,new Color(.12f,.42f,.53f),.4f);else if(battle.deployment&&battle.InDeployment(1,x,y))c=Color.Lerp(c,new Color(.5f,.15f,.1f),.23f);else if(reach.ContainsKey(entry.Key))c=Color.Lerp(c,new Color(.12f,.42f,.46f),.35f);entry.Value.sharedMaterial=Ground(c,t==5);}}
 }
 public void Effect(Vector3 from,Vector3 to,bool magic,bool blast){var go=new GameObject("Weapon effect");var line=go.AddComponent<LineRenderer>();line.positionCount=2;line.SetPosition(0,from+Vector3.up*.55f);line.SetPosition(1,to+Vector3.up*.4f);line.startWidth=magic?.12f:.065f;line.endWidth=.025f;line.material=Mat(magic?new Color(.3f,1,.85f):new Color(1,.7f,.27f),true);Destroy(go,.3f);if(blast){var boom=Shape(null,PrimitiveType.Sphere,to+Vector3.up*.3f,Vector3.one*1.3f,new Color(1,.45f,.1f),true);Destroy(boom,.18f);}Sound(magic?400:90);}
 void Sound(int freq){int n=6000;float[] samples=new float[n];for(int i=0;i<n;i++){float t=i/22050f;samples[i]=Mathf.Sin(t*freq*6.28f)*Mathf.Exp(-t*20)*.14f;}var clip=AudioClip.Create("Impact",n,1,22050,false);clip.SetData(samples,0);audioSource.PlayOneShot(clip);Destroy(clip,1);}
 public Vector2 ScreenPoint(Soldier u){var p=cam.WorldToScreenPoint(new Vector3(u.x,battle.P(u).titan?3.3f:.95f,u.y));return new Vector2(p.x,Screen.height-p.y);}
}
